from typing import List

def criticalConnections(V: int, adj: List[List[int]]) -> List[List[int]]:
    low = [0] * V
    disc = [0] * V
    parent = [-1] * V
    visited = [False] * V
    bridges = []
    time = 0

    def dfs(u):
        nonlocal time
        children = 0
        visited[u] = True
        disc[u] = low[u] = time
        time += 1

        for v in adj[u]:
            if not visited[v]:
                children += 1
                parent[v] = u
                dfs(v)

                low[u] = min(low[u], low[v])

                if parent[u] == -1 and children > 1:
                    bridges.append(sorted((u, v)))
                elif parent[u] != -1 and low[v] >= disc[u]:
                    bridges.append(sorted((u, v)))

            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

    for i in range(V):
        if not visited[i]:
            dfs(i)

    return sorted(bridges)
